import{_ as a,c as i,o as r,ag as t}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"Your learning hub: start here","description":"","frontmatter":{},"headers":[],"relativePath":"learner-guide/index.md","filePath":"learner-guide/index.md"}'),n={name:"learner-guide/index.md"};function s(o,e,l,d,c,p){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="your-learning-hub-start-here" tabindex="-1">Your learning hub: start here <a class="header-anchor" href="#your-learning-hub-start-here" aria-label="Permalink to “Your learning hub: start here”">​</a></h1><p>This guide is an orientation and study plan for the current hub, prepared 2026-10-28. <strong>For your current AI goal, start with <a href="./../applied-ai/">Build AI Apps — JavaScript First</a> and use <a href="./../ai-assisted-engineering/">AI for Software Development</a> alongside it.</strong> The <a href="./node-start.html#n-01-first-cli">Node N-01 route</a> remains available; the rest of the hub is available when a concrete need arises. Every learner assignment remains outstanding until you supply actual evidence.</p><h2 id="find-your-next-action" tabindex="-1"><span class="hub-section-number">1 </span>Find your next action <a class="header-anchor" href="#find-your-next-action" aria-label="Permalink to “1 Find your next action”">​</a></h2><ul><li><a href="./node-start.html">Node.js quick start and six milestones</a>: minimum reading, readiness and observable exit criteria.</li><li><a href="./ui.html">Illustrated application walkthrough</a>: desktop and narrow-screen navigation, lessons, examples and homework.</li><li><a href="./roadmap.html">Whole-hub roadmap and grouping rationale</a>: essential foundations, parallel study and optional continuations.</li><li><a href="./tracks.html">Track reading and homework sequences</a>: existing identifiers, dependencies and evidence.</li><li><a href="./topics.html">Complete topic mapping</a>: every inventoried substantive lesson with its roadmap placement and practice.</li><li><a href="./support.html">Supporting file mapping</a>: navigation, practice, examples, assets, external catalogues and historical records.</li><li><a href="./progress.html">Progress template and study cycle</a>: five separate kinds of progress.</li><li><a href="./verification.html">Verification and exact gaps</a>: what this guide checked and what remains unknown.</li></ul><h2 id="your-first-ai-session" tabindex="-1"><span class="hub-section-number">2 </span>Your first AI session <a class="header-anchor" href="#your-first-ai-session" aria-label="Permalink to “2 Your first AI session”">​</a></h2><p>Read <a href="./../applied-ai/javascript/orientation.html">AI orientation</a>, copy/run the <a href="./../workbench/applied-ai/javascript/">JavaScript starter</a>, and complete JS-01 offline. Then build the local chatbot before learning RAG or MCP. Keep <a href="./../practice/applied-ai/javascript-assistant.html">JS progress</a> separate from reference checks. Python remains <a href="./../python-for-ai/">optional depth</a>.</p><h2 id="a-first-node-js-session" tabindex="-1"><span class="hub-section-number">3 </span>A first Node.js session <a class="header-anchor" href="#a-first-node-js-session" aria-label="Permalink to “3 A first Node.js session”">​</a></h2><ol><li>Open the <a href="./../node-js/">Node path</a> and confirm you can explain functions, scope, objects, promises and try/catch. Use <a href="./../node-js/prerequisites-and-boundaries.html">specific prerequisite references</a> for gaps; completing the frontend curriculum is unnecessary.</li><li>Open <a href="./../practice/node-js/core-project.html">the analyzer specification</a>. Read its input contract and N-01 only. Keep this tab beside the <a href="./node-start.html">minimum reading</a>.</li><li>In a separate owned learner directory, write down expected valid, empty and invalid outcomes. Attempt the small CLI independently. Do not copy a finished homework solution.</li><li>Keep a <a href="./progress.html">progress record</a>, including uncertainty. Begin meaningful checks with the first increment; do not postpone them until N-05.</li></ol><p>Use synthetic logs, local files and loopback services. Preserve supplied Autocode build/Jest/database settings and restricted <code>src/tests</code>; run <code>npm run build</code>, <code>npm run test</code>, and Module 4&#39;s Cobertura coverage when applicable to your submission. The documentation repository itself has a separate documentation build.</p>',9)])])}const m=a(n,[["render",s]]);export{u as __pageData,m as default};
